// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

import java.util.Collections;

import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.junit.Test;

public class EnforcementSweepRetryTest extends AbstractEnforcementTest {

    private static final long RETRY_DELAY_SECONDS = 10;

    @Test
    public void failedListingSchedulesARetry() {
        givenContainerListingFailsOnce();

        whenEnforcementStarts();

        thenScheduledDelaysAre(RETRY_DELAY_SECONDS);
    }

    @Test
    public void retriedSweepChecksTheContainers() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenContainerListingFailsOnce();
        givenStartedEnforcement();

        whenScheduledDelayElapses();

        thenContainerWasDeleted(CONTAINER_ID);
    }

    @Test
    public void failedContainerCheckSchedulesARetry() {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenImageDigestLookupFailsOnceFor(CONTAINER_ID);

        whenEnforcementStarts();

        thenScheduledDelaysAre(RETRY_DELAY_SECONDS);
    }

    @Test
    public void retriedContainerCheckDeletesTheContainer() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenImageDigestLookupFailsOnceFor(CONTAINER_ID);
        givenStartedEnforcement();

        whenScheduledDelayElapses();

        thenContainerWasDeleted(CONTAINER_ID);
    }

    @Test
    public void failedStartEventCheckSchedulesARetry() {
        givenImageDigestLookupFailsOnceFor(CONTAINER_ID);
        givenStartedEnforcement();

        whenStartEventArrivesFor(CONTAINER_ID);

        thenScheduledDelaysAre(RETRY_DELAY_SECONDS);
    }

    @Test
    public void failedRemovalSchedulesARetry() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenContainerRemovalFailsOnce();

        whenEnforcementStarts();

        thenScheduledDelaysAre(RETRY_DELAY_SECONDS);
    }

    @Test
    public void retriedRemovalDeletesTheContainer() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenContainerRemovalFailsOnce();
        givenStartedEnforcement();

        whenScheduledDelayElapses();

        thenContainerRemovalWasAttempted(2);
    }

    @Test
    public void failuresWhileARetryIsPendingShareOneRetry() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenContainerRemovalAlwaysFails();
        givenStartedEnforcement();

        whenStartEventArrivesFor(CONTAINER_ID);

        thenScheduledDelaysAre(RETRY_DELAY_SECONDS);
    }

    @Test
    public void retryFailingAgainSchedulesTheNextRetry() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenContainerRemovalAlwaysFails();
        givenStartedEnforcement();

        whenScheduledDelayElapses();

        thenScheduledDelaysAre(RETRY_DELAY_SECONDS, RETRY_DELAY_SECONDS);
    }

    @Test
    public void retryDroppedAtCloseDoesNotBlockRetriesAfterRestart() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenContainerRemovalAlwaysFails();
        givenStartedEnforcement();
        givenClosedEnforcement();

        whenEnforcementStarts();

        thenScheduledDelaysAre(RETRY_DELAY_SECONDS, RETRY_DELAY_SECONDS);
    }

    private void givenContainerListingFailsOnce() {
        doThrow(new IllegalStateException("docker unreachable")).doAnswer(invocation -> runningContainers())
                .when(this.target).listContainerDescriptors();
    }

    private void givenImageDigestLookupFailsOnceFor(String containerId) {
        doThrow(new IllegalStateException("docker unreachable")).doReturn(Collections.singleton(IMAGE_DIGEST))
                .when(this.target).getImageDigestsByContainerId(containerId);
    }

    private void givenContainerRemovalFailsOnce() throws KuraException {
        doThrow(new KuraException(KuraErrorCode.OS_COMMAND_ERROR)).doNothing().when(this.target)
                .forceDeleteContainer(CONTAINER_ID);
    }

    private void givenContainerRemovalAlwaysFails() throws KuraException {
        doThrow(new KuraException(KuraErrorCode.OS_COMMAND_ERROR)).when(this.target).forceDeleteContainer(CONTAINER_ID);
    }

    private void thenContainerRemovalWasAttempted(int expectedTimes) throws KuraException {
        verify(this.target, times(expectedTimes)).forceDeleteContainer(CONTAINER_ID);
    }
}
